@startuml

class Employee {
  + name : string
  + socialSecurityNumber : string
}

class Planner extends Employee {}

class AdministrativeStaff extends Employee {
  + fieldOfActivity : string
  + username : string
  + password : string
}

class Driver extends Employee {}

class Customer {
  + name : string
  + billingAddress : string
}

class PartnerCompany {
  + name : string
  + address : string
}

class Vehicle {
  + licensePlate : string
  + mileage : int
}

class RefrigeratedTruck extends Vehicle {}

class SmallVan extends Vehicle {}

class LoadingPlatform extends Vehicle {}

class BoxTruck extends Vehicle {}

class RepairShop {
  + name : string
  + address : string
}

class Repair {
  + duration : string
  + cost : double
}

class Order {
  + packageSize : string
  + startTime : datetime
  + finishTime : datetime
  + comment : string
  + pickUpAddress : string
  + deliveryAddress : string
}

class Assignment {
}

class VehicleAssignment {
}

class OrderAssignment {
}

Employee "1" -- "0..*" Repair : takes vehicle to
Repair "0..*" -- "1" RepairShop : performed at
Repair "0..*" -- "1" Vehicle : for

Planner "1" -- "0..*" Order : assigns
Order "0..*" -- "1" Vehicle : uses
Order "0..*" -- "1" Driver : completed by
Order "0..*" -- "1" Customer : placed by
Order "0..*" -- "0..1" PartnerCompany : placed by

Order "1" -- "0..*" OrderAssignment
OrderAssignment "1" -- "1" Driver : assigned to
OrderAssignment "1" -- "1" Vehicle : assigned to

Vehicle "1" -- "0..*" VehicleAssignment
VehicleAssignment "1" -- "1" Driver : driven by

@enduml

